/// Whether `c`, a character with width above U+00FF, may continue the
/// cluster before it: most text (Latin, Cyrillic, Hebrew, Arabic, CJK, kana,
/// Hangul, fullwidth forms) can't, and is out after a compare or two.
#[inline]
pub(crate) fn may_continue(c: char) -> bool {
    let u = c as u32;
    if left_out(u) {
        return false;
    }
    // Emoji, regional indicators and skin tones: nearly the whole block,
    // the few others told apart where the cluster is.
    if (0x1f000..0x20000).contains(&u) {
        return true;
    }
    CONTINUING
        .binary_search_by(|&(start, end)| {
            if end < u {
                std::cmp::Ordering::Less
            } else if start > u {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// The characters `may_continue` takes as continuing nothing without the
/// table, most text first: what continues a cluster there is zero-width
/// (taken as such), but for Hangul syllables after a leading jamo and four
/// pictographs after a ZWJ.
#[inline]
fn left_out(u: u32) -> bool {
    (0x2e80..0xa800).contains(&u)
        || (0xac00..0xd7a4).contains(&u)
        || u < 0x900
        || (0xf900..0xff9e).contains(&u)
        || u >= 0x20000
}

/// Whether `c`, a character with width that may continue a cluster, is a
/// pictograph that continues one only after a ZWJ (GB11): most emoji.
pub(crate) fn pictographic(c: char) -> bool {
    let u = c as u32;
    (0x203c..0x20d0).contains(&u)
        || (0x2100..0x2c00).contains(&u)
        || (u >= 0x1f000 && !is_regional_indicator(c) && !(0x1f3fb..=0x1f3ff).contains(&u))
}

/// Whether `c` continues the cluster of `first` and the zero-width
/// characters `rest` joined to it (UAX #29).
pub(crate) fn continues(first: char, rest: &[char], c: char) -> bool {
    let mut buffer = [0; 64];
    let mut length = 0;
    for &part in std::iter::once(&first).chain(rest) {
        if length + 8 > buffer.len() {
            // A cluster longer than any of real text: as a string.
            let mut text: String = std::iter::once(first).chain(rest.iter().copied()).collect();
            let at = text.len();
            text.push(c);
            return !GraphemeCursor::new(at, text.len(), true)
                .is_boundary(&text, 0)
                .unwrap_or(true);
        }
        length += part.encode_utf8(&mut buffer[length..]).len();
    }
    let at = length;
    length += c.encode_utf8(&mut buffer[length..]).len();
    // SAFETY: the buffer holds only what `encode_utf8` wrote into it.
    let text = unsafe { std::str::from_utf8_unchecked(&buffer[..length]) };
    !GraphemeCursor::new(at, length, true)
        .is_boundary(text, 0)
        .unwrap_or(true)
}

/// What `c` does to the width of the cluster it continues, after `last`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Effect {
    /// Dropped: a variation selector after something with no emoji
    /// presentation.
    Ignore,
    /// Joined, the width as it was.
    NoChange,
    /// Joined, the cluster two cells wide.
    Wide,
    /// Joined, the cluster one cell wide.
    Narrow,
}

/// What `c` does to the cluster it continues, `last` the character before it.
pub(crate) fn effect(last: char, c: char) -> Effect {
    if c == VS16 || c == VS15 {
        if !is_variation_base(last) {
            return Effect::Ignore;
        }
        return if c == VS16 {
            Effect::Wide
        } else {
            Effect::Narrow
        };
    }
    if zero_in_cluster(c) {
        Effect::NoChange
    } else {
        Effect::Wide
    }
}

/// Whether `c` takes no width inside a cluster: a zero-width character, or
/// an emoji modifier (a colour patch alone, two wide).
fn zero_in_cluster(c: char) -> bool {
    c.width() == Some(0) || ('\u{1f3fb}'..='\u{1f3ff}').contains(&c)
}

