/// Whether `c` has both presentations, text and emoji.
pub(crate) fn is_variation_base(c: char) -> bool {
    VARIATION_BASES.binary_search(&(c as u32)).is_ok()
}

/// Whether `c` continues any cluster but a control (GB9): the variation
/// selectors, ZWJ, emoji modifiers and tags, told without segmenting.
pub(crate) fn always_continues(c: char) -> bool {
    matches!(c, VS15 | VS16 | '\u{200d}' | '\u{1f3fb}'..='\u{1f3ff}' | '\u{e0020}'..='\u{e007f}' | '\u{e0100}'..='\u{e01ef}')
}

/// A regional indicator, two cells wide in the mode, alone or as a flag.
pub(crate) fn is_regional_indicator(c: char) -> bool {
    ('\u{1f1e6}'..='\u{1f1ff}').contains(&c)
}

#[cfg(test)]
mod tests {
    use super::*;
    use unicode_segmentation::UnicodeSegmentation;

    /// Every character that continues a cluster is in the table (but those
    /// left out), and no other with width is.
    #[test]
    fn the_continuing_table_is_what_segmentation_says() {
        let before = [
            "a",
            "\u{1f1fa}",
            "\u{1f468}\u{200d}",
            "\u{1100}",
            "\u{1100}\u{1161}",
            "\u{ac00}",
            "\u{ac01}",
            "\u{915}\u{94d}",
        ];
        for u in 0x100..=0x10ffff {
            let Some(c) = char::from_u32(u) else { continue };
            let joins = before.iter().any(|before| {
                let mut text = String::from(*before);
                text.push(c);
                text.graphemes(true).count() == 1
            });
            let wide = c.width().unwrap_or(0) > 0;
            if joins && wide && pictographic(c) {
                // Only after a ZWJ.
                for before in ["a", "\u{1f1fa}", "\u{1100}", "\u{915}\u{94d}", "\u{1f600}"] {
                    let mut text = String::from(before);
                    text.push(c);
                    assert!(
                        text.graphemes(true).count() > 1,
                        "U+{u:04X} after {before:?}"
                    );
                }
            }
            if left_out(u) {
                // Out: what continues a cluster there is zero-width (taken
                // by `input` as such), but for Hangul syllables.
                assert!(!may_continue(c), "U+{u:04X}");
                assert!(
                    !(joins && wide)
                        || (0xac00..=0xd7a3).contains(&u)
                        || matches!(u, 0x3030 | 0x303d | 0x3297 | 0x3299),
                    "U+{u:04X}"
                );
            } else if joins {
                assert!(may_continue(c), "U+{u:04X} continues a cluster");
            } else if wide && !(0x1f000..0x20000).contains(&u) {
                assert!(!may_continue(c), "U+{u:04X} continues none");
            }
        }
    }

    #[test]
    fn what_always_continues_does() {
        let before = [
            "a",
            "\u{1f600}",
            "\u{2764}",
            "\u{1f1fa}",
            "\u{915}\u{94d}",
            "\u{1100}",
            " ",
        ];
        for c in [
            VS15,
            VS16,
            '\u{200d}',
            '\u{1f3fb}',
            '\u{1f3ff}',
            '\u{e0020}',
            '\u{e007f}',
            '\u{e0100}',
            '\u{e01ef}',
        ] {
            assert!(always_continues(c));
            for before in before {
                let mut text = String::from(before);
                text.push(c);
                assert_eq!(
                    text.graphemes(true).count(),
                    1,
                    "U+{:04X} after {before:?}",
                    c as u32
                );
            }
        }
    }

    #[test]
    fn widths_follow_ghostty() {
        assert_eq!(effect('\u{2764}', VS16), Effect::Wide);
        assert_eq!(effect('#', VS15), Effect::Narrow);
        assert_eq!(effect('\u{231a}', VS15), Effect::Narrow);
        assert_eq!(effect('x', VS16), Effect::Ignore);
        assert_eq!(effect('\u{1f600}', VS15), Effect::Ignore);
        assert_eq!(effect('\u{200d}', '\u{1f469}'), Effect::Wide);
        assert_eq!(effect('\u{1f44b}', '\u{1f3ff}'), Effect::NoChange);
        assert_eq!(effect('e', '\u{301}'), Effect::NoChange);
        assert_eq!(effect('\u{915}', '\u{93f}'), Effect::Wide);
        assert!(continues('\u{1f1fa}', &[], '\u{1f1f8}'));
        assert!(!continues('\u{1f1fa}', &['\u{1f1f8}'], '\u{1f1eb}'));
        assert!(continues('\u{1f468}', &['\u{200d}'], '\u{1f469}'));
        assert!(continues('\u{915}', &['\u{94d}'], '\u{937}'));
        assert!(!continues('a', &[], 'b'));
        assert!(!continues('a', &[], '\u{200b}'));
        assert!(continues('e', &['\u{301}'; 40], '\u{302}'));
    }
}
